    in attribute io_1 : Boolean;
    in attribute io_2 : Boolean;
    in attribute io_3 : Boolean;
    attribute prevBed1 : Boolean := false;
    attribute prevBed2 : Boolean := false;
    attribute prevBed3 : Boolean := false;
    attribute prevAck : Boolean := false;
    attribute pending : Boolean := false;
    attribute activeBed : Integer := 0;
    attribute queueSeq : Integer := 0;
    perform action tick {
      first start;
      then if ((io_0) and ((not prevBed1))) {
        first start;
        then assign pending := true;
        then assign activeBed := 1;
        then assign queueSeq := queueSeq + 1;
      }
      then if ((io_1) and ((not prevBed2))) {
        first start;
        then assign pending := true;
        then assign activeBed := 2;
        then assign queueSeq := queueSeq + 1;
      }
      then if ((io_2) and ((not prevBed3))) {
        first start;
        then assign pending := true;
        then assign activeBed := 3;
        then assign queueSeq := queueSeq + 1;
      }
      then if ((io_3) and ((not prevAck))) {
        first start;
        then assign pending := false;
        then assign activeBed := 0;
      }
      then assign prevBed1 := io_0;
      then assign prevBed2 := io_1;
      then assign prevBed3 := io_2;
      then assign prevAck := io_3;
    }
    out attribute io_4 : Boolean = pending;
    out attribute io_5 : Integer = (if pending ? 1000 else 0);
    out attribute io_6 : Integer = (if pending ? 1000 else 0);
  }
  part system : Controller;
}
